    # Handle standard escape sequences
    if escape_id in BASIC_STR_ESCAPE_REPLACEMENTS:
        return pos + 2, BASIC_STR_ESCAPE_REPLACEMENTS[escape_id]

    # Handle Unicode scalar escape sequences
    if escape_id.startswith("\\u"):
